import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch108Test {
    static final UUID A=DynamicPassiveModifierTest.A,B=DynamicPassiveModifierTest.B;
    static final List<String> IDS=List.of("sm9_en_134");
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static void settle(ServerMatch m){NonPokemonBatch103Test.settle(m);}
    static void damage(ServerMatch m,UUID actor,UUID owner,UUID host,int amount){NonPokemonBatch51Test.damage(m,actor,owner,host,amount/10);}
    static CardInstance energy(ServerMatch m,UUID owner,UUID target,String id){var card=hand(m,owner,id);m.attachEnergyByEffect(m.currentPlayer(),owner,EffectSourceZone.HAND,card.instanceId(),owner,target);return card;}
    static ServerMatch game(EnergyType type,EnergyType energy,TrainerProfile tool,TrainerProfile item,AttackDefinition attack){
        var kinds=List.of("basic","basic","evolved","trainer","tool","energy","special","item");var defs=new ArrayList<CardDefinition>();
        for(String id:new LinkedHashSet<>(kinds)){boolean pokemon=Set.of("basic","evolved").contains(id),en=Set.of("energy","special").contains(id);defs.add(new CardDefinition(id,id,pokemon?CardCategory.POKEMON:en?CardCategory.ENERGY:CardCategory.TRAINER,id.equals("trainer")?TrainerCategory.STADIUM:id.equals("tool")?TrainerCategory.TOOL:id.equals("item")?item.category():TrainerCategory.NONE,"H",Set.of("international"),id.equals("basic"),id.equals("energy"),60,id.equals("trainer")?Map.of("棱镜之星",1):Map.of(),EffectSupport.SUPPORTED,null));}
        var profiles=Map.of("basic",new PokemonProfile(500,1,null,null,0,null,0,1,List.of(attack),List.of(),type),"evolved",new PokemonProfile(600,1,"basic",null,0,null,0,1,List.of(attack),List.of(),EnergyType.WATER));
        var combat=new CombatCatalog(profiles,Map.of("energy",energy),Map.of("trainer",profile(IDS.getFirst()),"tool",tool,"item",item),Map.of("special",EnergyProfile.fixed(EnergyType.DARKNESS,2)));
        for(int seed=0;seed<1000;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,kinds.get(i%kinds.size())));decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,30);m.drawCardsByEffect(A,B,30);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().allMatch(p->new HashSet<>(kinds).stream().allMatch(id->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(id)))))return m;}throw new AssertionError("Black Market fixture unavailable");
    }
    static ServerMatch game(AttackDefinition attack){return game(EnergyType.DARKNESS,EnergyType.DARKNESS,profile("swsh5_en_126"),DynamicPassiveModifierTest.plainStadium(),attack);}
    static ServerMatch aiGame(String id){var m=game(GeneratedRuleBatch8Test.hit(200,false));for(UUID p:List.of(A,B))energy(m,p,active(m,p),"energy");return m;}
    static void play(ServerMatch m,UUID p){m.playTrainer(p,hand(m,p,"trainer").instanceId(),null);}
    static int prizes(ServerMatch m,UUID p){return m.privateView(p).prizes().size();}
    public static void main(String[] args){scope();causes();afterText();share();stacking();protection();ai();schema();System.out.println("NonPokemonBatch108Test passed: Black Market both fields, Basic/Special Darkness energy and current type, Active/Bench attack-damage KOs, counters/poison/self/effect exclusions, post-attack Stadium/Energy removal, Exp. Share pre-reaction snapshot, additive unclamped prize reductions/bonuses, Prism protection and Lost Zone, four AI difficulties");}
    static void scope(){for(UUID owner:List.of(A,B))for(boolean benched:List.of(false,true))for(String mode:List.of("basic","special","wrong-energy","wrong-type","none")){
        var m=game(mode.equals("wrong-type")?EnergyType.GRASS:EnergyType.DARKNESS,mode.equals("wrong-energy")?EnergyType.FIRE:EnergyType.DARKNESS,profile("swsh5_en_126"),DynamicPassiveModifierTest.plainStadium(),GeneratedRuleBatch8Test.hit(100,benched));if(owner.equals(B))m.endTurn(A);UUID target=benched?bench(m,owner):active(m,owner);play(m,owner);if(!mode.equals("none"))energy(m,owner,target,mode.equals("special")?"special":"energy");damage(m,owner,owner,target,400);m.endTurn(owner);int before=prizes(m,other(owner));m.attack(other(owner),"hit");settle(m);check(before-prizes(m,other(owner))==(Set.of("basic","special").contains(mode)?0:1),"Black Market scope mismatch: "+owner+benched+mode);
    }}
    static void causes(){for(String cause:List.of("counters","poison","effect","self","evolved")){
        var attack=cause.equals("counters")?DeckDiscardTriggeredAbilityTest.attack(0,"{\"type\":\"damage_counter\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":10}"):cause.equals("self")?DeckDiscardTriggeredAbilityTest.attack(0,"{\"type\":\"self_damage\",\"target\":\"SELF\",\"amount\":100}"):GeneratedRuleBatch8Test.hit(100,false);var m=game(attack);UUID target=active(m,A);play(m,A);energy(m,A,target,"energy");if(cause.equals("evolved"))m.evolveByEffect(A,target,hand(m,A,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);damage(m,A,A,target,(cause.equals("evolved")?600:500)-(cause.equals("poison")?10:100));int before=prizes(m,B);
        if(cause.equals("effect"))m.knockOutPokemonByEffect(A,A,target);else if(cause.equals("poison")){m.applySpecialConditionByEffect(A,A,SpecialCondition.POISONED);m.endTurn(A);}else if(cause.equals("self"))m.attack(A,"hit");else{m.endTurn(A);m.attack(B,"hit");}settle(m);check(before-prizes(m,B)==1,"Black Market applied to wrong cause or stale Darkness type: "+cause);
    }}
    static void afterText(){for(boolean before:List.of(false,true))for(boolean stadium:List.of(false,true)){
        String effect=stadium?"{\"type\":\"discard_stadium\"}":"{\"type\":\"discard_energy\",\"target\":\"OPPONENT_ACTIVE\",\"amount\":1,\"minimum\":1}";var attack=BeforeDamageAttackTest.attack(before?effect:"","",before?"":effect);var m=game(attack);play(m,A);energy(m,B,active(m,B),"energy");damage(m,A,B,active(m,B),460);int count=prizes(m,A);m.attack(A,"hit");settle(m);check(count-prizes(m,A)==1,"KO captured Black Market before attack text finished");
    }}
    static void share(){for(UUID owner:List.of(A,B)){var m=game(GeneratedRuleBatch8Test.hit(100,false));if(owner.equals(B))m.endTurn(A);UUID target=active(m,owner),receiver=bench(m,owner);play(m,owner);m.playTrainer(owner,hand(m,owner,"tool").instanceId(),receiver);var en=energy(m,owner,target,"energy");damage(m,owner,owner,target,400);m.endTurn(owner);m.attack(other(owner),"hit");var trigger=m.triggerOrderPrompt();check(trigger!=null&&trigger.optionalDecision(),"Exp. Share did not ask for optional use");m.decideTriggeredEffect(owner,trigger.id(),true);var q=m.effectCardPrompt(owner);check(q!=null&&q.candidates().contains(en),"Exp. Share failed to offer actual energy before disposal");m.submitEffectCards(owner,q.resolutionId(),q.step(),List.of(en.instanceId()));settle(m);check(EventTargetBindingTest.field(m).attachedEnergy(owner,receiver).contains(en),"Exp. Share failed movement");check(prizes(m,other(owner))==6,"KO reaction energy movement revoked Black Market reduction");}}
    static void stacking(){String bonus="{\"type\":\"extra_prize_on_attack_ko\",\"target\":\"SELF\",\"amount\":2,\"basic_only\":false}";var m=game(EnergyType.DARKNESS,EnergyType.DARKNESS,profile("bw9_en_107"),DynamicPassiveModifierTest.plainStadium(),DeckDiscardTriggeredAbilityTest.attack(100,bonus));play(m,A);energy(m,A,active(m,A),"energy");m.playTrainer(A,hand(m,A,"tool").instanceId(),active(m,A));damage(m,A,A,active(m,A),400);m.endTurn(A);m.attack(B,"hit");settle(m);check(prizes(m,B)==5,"Prize reductions were clamped before +2 attack bonus");}
    static void protection(){for(String removal:List.of("item","supporter","attack","replace")){
        var item=removal.equals("supporter")?profile("sm8_en_173"):removal.equals("replace")?DynamicPassiveModifierTest.plainStadium():DeckDiscardTriggeredAbilityTest.trainer("ITEM","{\"type\":\"discard_stadium\",\"target\":\"SELF\"}");var attack=BeforeDamageAttackTest.attack("","","{\"type\":\"discard_stadium\"}");var m=game(EnergyType.DARKNESS,EnergyType.DARKNESS,DynamicPassiveModifierTest.plainTool(),item,attack);var card=hand(m,A,"trainer");play(m,A);if(removal.equals("attack"))m.attack(A,"hit");else{if(removal.equals("replace"))m.endTurn(A);UUID p=m.currentPlayer();m.playTrainer(p,hand(m,p,"item").instanceId(),null);if(removal.equals("supporter")){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(card.instanceId()));}}settle(m);boolean gone=Set.of("attack","replace").contains(removal);check(m.privateView(A).lostZone().contains(card)==gone&&!m.privateView(A).discard().contains(card),"Prism protection/replacement destination mismatch: "+removal);if(!gone)check(m.clientView(A).stadium().instanceId().equals(card.instanceId()),"Protected Stadium changed");
    }}
    static void ai(){for(var level:AiDifficulty.values()){var m=aiGame(IDS.getFirst());play(m,A);var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"Black Market AI stalled");}}
    static void schema(){var e=profile(IDS.getFirst()).ongoingProgram().triggers().getFirst().effects().stream().filter(x->x.type().equals("prize_card_modifier")).findFirst().orElseThrow();for(var source:List.of(PassiveModifierProgram.Source.TOOL,PassiveModifierProgram.Source.ENERGY,PassiveModifierProgram.Source.ABILITY))GeneratedRuleBatch8Test.reject(()->PassiveModifierProgram.validate(new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.PASSIVE,List.of(),List.of(e)))),source));}
}
